print(f"Total samples: {len(samples)}")
all_valid = True
for idx, pair in enumerate(samples):
    v_ok, v_reason = validate_pair(pair)
    c_res, c_reason = clean_sample(pair["raw_asr"], pair["refined_text"])
    w_count = len(pair["refined_text"].split())
    
    tier = "short" if w_count < 25 else ("medium" if w_count < 90 else "long")
    status = "PASS" if (v_ok and c_res is not None) else "FAIL"
    if status == "FAIL":
        all_valid = False
        print(f"Sample {idx+1} [{tier}, {w_count} words]: FAIL -> Validator: {v_reason} | Cleaner: {c_reason}")
    else:
        print(f"Sample {idx+1} [{tier}, {w_count} words]: PASS")

b_ok, b_msg, tiers = validate_batch(samples, min_short=4, min_medium=6, min_long=10)
print(f"\nBatch validation: ok={b_ok}, msg={b_msg}, tiers={tiers}")
